import SwiftUI
import PhotosUI
struct AddRecipeView:View{
 @Environment(AppStore.self)private var store;@Environment(\.dismiss)private var dismiss;@State private var link="";@State private var manual=false;@State private var imported:Recipe?;@State private var photo:PhotosPickerItem?
 var body:some View{VStack(spacing:18){Text("Add a Recipe").font(RecipeTheme.title()).frame(maxWidth:.infinity,alignment:.leading);TextField("Paste a recipe link",text:$link).textInputAutocapitalization(.never).keyboardType(.URL).padding().background(.thinMaterial,in:RoundedRectangle(cornerRadius:16));Button("Import from Link"){imported=store.importURL(link)}.buttonStyle(PrimaryButtonStyle());PhotosPicker(selection:$photo,matching:.images){Label("Import from Photos",systemImage:"photo").frame(maxWidth:.infinity)}.buttonStyle(.bordered);Button{manual=true}label:{Label("Create Manually",systemImage:"square.and.pencil").frame(maxWidth:.infinity)}.buttonStyle(.bordered);Spacer()}.padding().background(RecipeTheme.paper).navigationTitle("Add").navigationBarTitleDisplayMode(.inline).toolbar{Button("Close"){dismiss()}}.alert("Couldn’t import",isPresented:.init(get:{store.lastError != nil},set:{if !$0{store.lastError=nil}})){Button("OK"){store.lastError=nil}}message:{Text(store.lastError ?? "")}.sheet(item:$imported){r in NavigationStack{RecipeEditorView(recipe:r)}}.sheet(isPresented:$manual){NavigationStack{RecipeEditorView(recipe:Recipe(title:"",sourceURL:nil,servings:2,minutes:0,isFavorite:false,needsReview:true,ingredients:[],steps:[]))}}.onChange(of:photo){_,new in if new != nil{manual=true}}}
}
